import 'dart:convert';
import 'dart:typed_data';

import 'package:flutter/material.dart';

class BrilhartLogo extends StatelessWidget {
  const BrilhartLogo({super.key, this.height = 72, this.width, this.fit = BoxFit.contain});

  final double height;
  final double? width;
  final BoxFit fit;

  static final Uint8List _bytes = base64Decode(_logoBase64);

  @override
  Widget build(BuildContext context) {
    return Image.memory(
      _bytes,
      height: height,
      width: width,
      fit: fit,
      gaplessPlayback: true,
      filterQuality: FilterQuality.high,
    );
  }
}

const String _logoBase64 = r'''''';
